Betrachten Sie den Quellcode:
float Wurzel(float Zahl) {
  float Wert = 0.0;
  if (Zahl > 0) {
    Wert = 2.0;
    while (abs(Wert*Wert-Zahl) > 0.01) {
      Wert = Wert - ((Wert*Wert-Zahl) / (2.0*Wert));
    }
  }
  return Wert;
}
